mapper.select:
SELECT i.id, i.title, i.price, i.status, i.seller_id, u.nickname AS seller_nickname, u.avatar_url AS seller_avatar_url, i.category_id, cat.name AS category_name, i.campus_id, c.name AS campus_name, i.admin_lock, i.off_shelf_reason, i.favorite_count, i.view_count, i.created_at, i.updated_at FROM items i JOIN users u ON u.id = i.seller_id LEFT JOIN categories cat ON cat.id = i.category_id LEFT JOIN campuses c ON c.id = i.campus_id
AND i.status IN
#{status}
AND i.seller_id = #{sellerId}
AND i.title LIKE #{keyword} ESCAPE '!'
ORDER BY i.created_at DESC, i.id DESC
